head.script:
/**
 * @component
 * @componentName udc_date
 * @pluginName
 * @company
 * @developer
 * @category /cm/gcc
 * @notSupportBrowser
 * @version
 * @htmlRender
 * @icon
 * @disableIcon
 * @description
 * @width
 * @height
 * @license
 * @imagePath
 * @homepage
 */

scwin.onpageload = function() {

};

/**
 * @method
 * @name addMinute
* @description 入力された日付に指定された分数を加算する。
* @param {String} pYmd 日付形式の文字列 (yyyyMMdd または yyyyMMddHHmmss)
* @param {Number} offset 加算する分数
* @returns {String} 指定されたoffset分の日付が加算された日付
 * @hidden N
 * @exception 
 * @example 
$c.date.addMinute("201708191210", 10); // "201708191220"
$c.date.addMinute("201708191210", -10); // "201708191200"
 */ 
scwin.addMinute = function(pYmd, offset) {
	return WebSquare.date.dateTimeAdd(pYmd, offset, "minute");
};


/**
 * @method
 * @name addHour
* @description 入力された日付に指定された時間を加算する。
* @param {String} pYmd 日付形式の文字列 (yyyyMMdd または yyyyMMddHHmmss)
* @param {Number} offset 加算する時間数。
* @returns {String} 指定されたoffset分の日付が加算された入力日付
 * @hidden N
 * @exception 
 * @example 
$c.date.addHour("2017081912", 10); // "2017081922"
$c.date.addHour("2017081912", -10); // "2017081902"
 */ 
scwin.addHour = function(pYmd, offset) {
	return WebSquare.date.dateTimeAdd(pYmd, offset, "hour");
};

/**
 * @method
 * @name addDate
* @description 入力された日付に指定された日数を加算する。
* @param {String} pYmd 日付形式の文字列 (yyyyMMdd または yyyyMMddHHmmss)
* @param {Number} offset 加算する日数。
* @returns {String} 指定されたoffset分の日付が加算された入力日付
 * @hidden N
 * @exception 
 * @example 
$c.date.addDate("20170819", 2); // "20170821"
$c.date.addDate("20170819", -10); // "20170809"
 */ 
scwin.addDate = function(pYmd, offset) {
	return WebSquare.date.dateAdd(pYmd, offset);
};

/**
 * @method
 * @name addMonth
* @description 入力された日付に指定された月数を加算する。
* @param {String} pYmd 日付形式の文字列 (yyyyMMdd または yyyyMMddHHmmss)
* @param {Number} offset 加算する月数。
* @returns {String} 指定されたoffset分の月数が加算された入力日付
 * @hidden N
 * @exception 
 * @example
$c.date.addMonth("20170819", 2); // "20171019"
$c.date.addMonth("20170819", -10); // "20161019"
 */ 
scwin.addMonth = function(pYmd, offset) {
	try {
		let date = "";
		const isDate = $c.date.isDate(pYmd);

		if (!isDate) {
			return;
		}
		if (typeof offset == "undefined" || isNaN(offset)) {
			offset = 0;
		}

		let dY = (pYmd + "").substring(0, 4);
		let dM = (pYmd + "").substring(4, 6);
		let dD = (pYmd + "").substring(6, 8);
		let dTime = (pYmd + "").substring(8);
		dM = (dM * 1) + (offset * 1);

		if (dM > 0) {
			dY = (dY * 1) + Math.floor(dM / 12);
			dM = dM % 12;
		} else {
			dY = (dY * 1) - Math.floor((dM * -1 + 12) / 12);
			dM = dM % 12 + 12;
		}

		if (Number(dD) >= 30) {
			const chkMonth1 = [ 2 ];
			const chkMonth2 = [ 4, 6, 9, 11 ];

			if (chkMonth1.indexOf(dM) > -1) {
				if ($c.date.isLeafYear(dY + "01" + "01")) {
					dD = "29";
				} else {
					dD = "28";
				}
			} else if (chkMonth2.indexOf(dM) > -1) {
				if (Number(dD) > 30) {
					dD = "30";
				}
			}
		}
		const cDate = new Date(dY, dM - 1, dD);
		const cYear = cDate.getFullYear();
		let cMonth = cDate.getMonth() + 1;
		if ((cMonth + "").length < 2) {
			cMonth = "0" + cMonth;
		}
		const cDay = cDate.getDate();
		if ((cDay + "").length < 2) {
			cDay = "0" + cDay;
		}
		date = cYear + "" + cMonth + "" + cDay + "" + dTime;
		return date;
	} catch (ex) {
		console.error(ex);
	}
};


/**
 * @method
 * @name getServerDateTime
* @description サーバーの日付を返します。(デフォルトフォーマット: yyyyMMdd)
* @param {String:N} sDateFormat 日付フォーマット
 * y Year 1996; 96
 * M Month in year 07
 * d Day in month 10
 * H Hour in day (0-23) 0
 * m Minute in hour 30
 * s Second in minute 55
 * S Millisecond 978
* @returns {String} 現在の日付
 * @hidden N
 * @exception 
 * @example
$c.date.getServerDateTime("yyyy-MM-dd HH:mm:ss SSS");
$c.date.getServerDateTime("yyyy-MM-dd");
$c.date.getServerDateTime();
 */ 
scwin.getServerDateTime = function(sDateFormat) {
	if ($c.util.isEmpty(sDateFormat)) {
		sDateFormat = "yyyyMMdd";
	}

	return WebSquare.date.getCurrentServerDate(sDateFormat);
};

/**
 * @method
 * @name formatDate
* @description 文字列に日付フォーマッターを適用して返す。
* @param {String} str フォーマッタを適用するパラメータ（StringまたはNumber型をサポート）
* @param {String} type 適用するフォーマッターの形式 Default:null,slash,date
* @returns {String} フォーマッターが適用された文字列
 * @hidden N
 * @exception 
 * @example
$c.date.formatDate(20120319, "slash"); 
// return 例) 12/03/19

$c.date.formatDate(20120319, "date");
// 戻り値の例) 2012/03/19

$c.date.formatDate(20120319, "colon");
// 戻り値の例) 2012:03:19

$c.date.formatDate(20120319);
// return 例) 2012年03月19日
 */ 
scwin.formatDate = function(str, type) {
	if(typeof($p) == 'string') {
		type = str;
		str = $p;
		return scwin.__formatDate(str, type);
	}
	return scwin.__formatDate(str, type);
};

/**
 * @method
 * @name __formatDate
* @description パラメータとして$pを渡さないformatDate関数
* @param {String} str 日付データ
* @param {String} type 日付データフォーマット
 * @returns {String} 
 * @hidden Y
 * @exception
 * @example
 */
scwin.__formatDate = function(str, type) {
	let output = "";
	let date = new String(str);

	if (type == "slash") {
		date = date.substring(2, date.length);
		for (let i = 0; i <= date.length - 1; i++) {
			output = output + date[i];
			if ((i + 1) % 2 == 0 && (date.length - 1) !== i)
				output = output + "/";
		}
	} else if (type == "date") {
		if (date.length == 8) {
			output = date.substr(0, 4) + "/" + date.substr(4, 2) + "/" + date.substr(6, 2);
		}
	} else if (type == "colon") {
		if (date.length == 8) {
			output = date.substr(0, 4) + ":" + date.substr(4, 2) + ":" + date.substr(6, 2);
		}
	} else if (!$c.util.isEmpty(type)) {
		if (date.length == 8) {
			output = date.substr(0, 4) + type + date.substr(4, 2) + type + date.substr(6, 2);
		}
	} else {
		const year = date.substr(0, 4);
		const month = date.substr(4, 2);
		const day = date.substr(6, 2);
output = year + "年 " + month + "月 " + day + "日";
	}

	return output;
};


/**
 * @method
 * @name formatTime
* @description 時間 - 入力されたStringまたはNumberにフォーマッターを適用して返す。
* @param {String} value 時間Formatterを適用した値（String型またはNumber型をサポート）
* @returns {String} フォーマッターが適用された文字列
 * @hidden N
 * @exception 
 * @example
$c.date.formatTime("123402");
// 戻り値の例) "12:34:02"
 */ 
scwin.formatTime = function(value) {
	const hour = String(value).substr(0, 2);
	const minute = String(value).substr(2, 2);
	const second = String(value).substr(4, 2);
	const output = hour + ":" + minute + ":" + second;

	return output;
};


/**
 * @method
 * @name formatDateTime
* @description 日付オブジェクトにフォーマットを適用する。(デフォルトフォーマット: yyyyMMdd)
* @param {Date} 日付フォーマットを適用する日付オブジェクト
* @param {String:N} sDateFormat 日付フォーマット
 * y Year 1996; 96
 * M Month in year 07
 * d Day in month 10
 * H Hour in day (0-23) 0
 * m Minute in hour 30
 * s Second in minute 55
 * S Millisecond 978
* @returns {String} 現在の日付
 * @hidden N
 * @exception 
 * @example
$c.date.formatDateTime(new Date());  // "20190822"
$c.date.formatDateTime(new Date(), "yyyy-MM-dd HH:mm:ss SSS");  // "2019-08-22 15:55:35 705"
 */ 
scwin.formatDateTime = function(value, sDateFormat) {
	if ($c.util.isEmpty(sDateFormat)) {
		sDateFormat = "yyyyMMdd";
	}

	return WebSquare.date.getFormattedDate(value, sDateFormat);
};

/**
 * @method
 * @name isDate
* @description 入力された値がDate形式の値かどうかを確認します。
* @param {String|number} sDate 日付文字列 (yyyyMMdd または yyyyMMddHHmmss)
* @param {Boolean} timeChk 時間チェック。(true/false)
* @returns {Boolean} 日付形式に一致する場合はtrue、そうでない場合はfalse
 * @hidden N
 * @exception 
 * @example
$c.date.isDate("20170819"); // return true
 */ 
scwin.isDate = function(sDate, timeChk) {
	let flag = true;
	try {
		if (sDate.length == 8) {
			sDate = sDate + "000000";
		}

		const y1 = parseInt(sDate.substring(0, 4), 10);
		const m1 = parseInt(sDate.substring(4, 6), 10);
		const d1 = parseInt(sDate.substring(6, 8), 10);
		const h1 = parseInt(sDate.substring(8, 10), 10);
		const t1 = parseInt(sDate.substring(10, 12), 10);
		const s1 = parseInt(sDate.substring(12), 10);
		if (isNaN(y1) || isNaN(m1) || isNaN(d1) || isNaN(h1) || isNaN(t1) || isNaN(s1))
			flag = false;

		if (m1 < 1 || m1 > 12)
			flag = false;

		let maxDay = 31;
		if (m1 == 2) {
			maxDay = ((y1 % 400 == 0) || ((y1 % 4 == 0) && (y1 % 100 != 0))) ? 29
					: 28;
		} else if (m1 == 4 || m1 == 6 || m1 == 9 || m1 == 11) {
			maxDay = 30;
		}

		if (d1 < 1 || d1 > maxDay) {
			flag = false;
		}

		if (h1 + t1 + s1 != "") {
			if (h1 < 0 || h1 > 24) {
				flag = false;
			} else if (h1 == 24) {
				if(typeof timeChk == "boolean" && !timeChk)
					flag = false;
				if (t1 > 0)
					flag = false;
				if (s1 > 0)
					flag = false;
			}
			if (t1 < 0 || t1 > 59)
				flag = false;
			if (s1 < 0 || s1 > 59)
				flag = false;
		}
	} catch (ex) {
		console.error(ex);
		flag = false;
	}
	return flag;
};

/**
 * @method
 * @name diffDate
* @description fromDateとtoDateを入力として受け取り、二つの日付の差を返します。
* @param {String} fromDate 開始日付 (日付形式はyyyyMMdd又はyyyyMMddHHmmss)
* @param {String} toDate 終了日付 (日付形式はyyyyMMdd又はyyyyMMddHHmmss)
* @returns {Number} 終了日から開始日までの日数差。
 * @hidden N
 * @exception 
 * @example
$c.date.diffDate("20170821", "20180621"); // 304
 */ 
scwin.diffDate = function(fromDate, toDate) {
	try {
		if (!$c.date.isDate(fromDate) || !$c.date.isDate(toDate)) {
			return;
		}
		const diffDate = WebSquare.date.dateDiff(fromDate, toDate);
		return diffDate;
	} catch (ex) {
		console.error(ex);
	}
};

/**
 * @method
 * @name isLeafYear
* @description 入力された西暦の日付が閏年かどうかを検査する。
* @param {String} pYmd :: I :: Y ::  :: 閏年確認日付。
* @returns {Boolean} 閏年の有無（true：閏年）
 * @hidden N
 * @exception 
 * @example
$c.date.isLeafYear("20201212");  // return true
 */ 
scwin.isLeafYear = function(pYmd) {
	try{
		let isLeafYear = false;
		if (!$c.date.isDate(pYmd)) {
			return;
		} else {
			pYmd = pYmd.substr(0, 8);
			const y1 = parseInt( pYmd.substr(0, 4), 10);
			isLeafYear = ((y1 % 400 == 0 ) || ((y1 % 4 == 0) && (y1 % 100 != 0))) ? true : false;
		}
		return isLeafYear;
	} catch (ex) {
		console.error(ex);
	}
};

/**
 * @method
 * @name getDay
* @description 特定の日付の曜日を返す。
* @param {String} value "yyyyMMdd"フォーマット形式の日付を表す文字列 ("20190801")
* @param {String} type 戻り値の形式。デフォルトは日付を日本語で返す。numの場合は数字で返す。日曜日：1 ～ 土曜日：7
* @returns {String} 曜日
 * @hidden N
 * @exception 
 * @example
$c.date.getDay("20190822");  // "木曜日"
$c.date.getDay("20190824");  // "土曜日"
 */ 
scwin.getDay = function(value,type) {
	let dayVal;
	if (type == "num") {
		dayVal = WebSquare.date._getDay(value);
		if (dayVal == 0 ) {
			return "7";
		}else{
			return String(dayVal);
		}
	} else {
		return WebSquare.date.getDay(value);
	}
};

/**
 * @method
 * @name getLunar
* @description 特定の日付の旧暦の日付を返す。
* @param {String} value "yyyyMMdd"フォーマット形式の日付を表す文字列
* @returns {String} 旧暦の日付
 * @hidden N
 * @exception 
 * @example
$c.date.getLunar("20190824");  // "20190724"
 */ 
scwin.getLunar = function(value) {
	return  WebSquare.date.toLunar(value);
};

/**
 * @method
 * @name getLastDateOfMonth
* @description 該当月の最終日を返します。
* @param {String} yearMonth 年月の文字列 (yyyyMM)
* @returns 最終日
 * @hidden N
 * @exception 
 * @example
$c.date.getLastDateOfMonth("201510");  // 31
 */ 
scwin.getLastDateOfMonth = function(yearMonth) {
	try {
		if (typeof yearMonth !== "string") {
			yearMonth = $c.str.serialize(yearMonth);
		}

		const year = yearMonth.substring(0, 4);
		const month = yearMonth.substring(4, 6);

		return (new Date(year, month, 0)).getDate();
	} catch(ex) {
		console.error(ex);
		return null;
	}
};
